<?php require __DIR__.'/../bootstrap.php';$token=preg_replace('/[^a-f0-9]/i','',(string)($_GET['token']??''));$q=db()->prepare('SELECT title,token,privacy,status FROM code_snippets WHERE token=?');$q->execute([$token]);$s=$q->fetch();if(!$s||$s['status']!=='active'||$s['privacy']==='private'){http_response_code(404);exit('Code not found.');}$url=code_public_url($s['token']);require __DIR__.'/../includes/header.php';?><div class="page-head"><div><span class="eyebrow">CODE QR</span><h1><?=e($s['title'])?></h1><p><?=e($url)?></p></div></div><section class="card"><div class="grid-main"><div><label>Foreground <input type="color" id="fg" value="#111827"></label><label>Background <input type="color" id="bg" value="#ffffff"></label><label>Resolution <input id="size" type="number" min="128" max="2048" value="768"></label><button class="btn" id="refresh">Generate</button><button class="btn secondary" id="svg">Download SVG</button><button class="btn secondary" id="png">Download PNG</button></div><div id="box" style="display:grid;place-items:center;min-height:340px"></div></div></section><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcode-generator/1.4.4/qrcode.min.js"></script><script>const U=<?=json_encode($url)?>;let render=()=>{const qr=qrcode(0,'H');qr.addData(U);qr.make();const size=Math.min(2048,Math.max(128,+document.getElementById('size').value||768));let svg=qr.createSvgTag({cellSize:Math.max(2,Math.floor(size/qr.getModuleCount())),margin:4,scalable:true,alt:U});const box=document.getElementById('box');box.innerHTML=svg;const s=box.querySelector('svg');s.setAttribute('width',size);s.setAttribute('height',size);s.style.background=document.getElementById('bg').value;box.querySelectorAll('rect').forEach(r=>{if(r.getAttribute('fill')&&r.getAttribute('fill')!=='none')r.setAttribute('fill',document.getElementById('fg').value)});};document.getElementById('refresh').onclick=render;document.getElementById('svg').onclick=()=>{const x=new XMLSerializer().serializeToString(document.querySelector('#box svg'));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([x],{type:'image/svg+xml'}));a.download='pocketcat-code-qr.svg';a.click()};document.getElementById('png').onclick=()=>{const x=new XMLSerializer().serializeToString(document.querySelector('#box svg'));const i=new Image();i.onload=()=>{const c=document.createElement('canvas'),n=+document.getElementById('size').value||768;c.width=c.height=n;c.getContext('2d').drawImage(i,0,0,n,n);const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download='pocketcat-code-qr.png';a.click()};i.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(x)};render();</script><?php require __DIR__.'/../includes/footer.php'; ?>